import { launchServer } from './launch.js';
export function bootstrap(settings) {
  const idleMs = settings.get<number>(
    'HTTP_IDLE_MS',
    0,
  );
  if (!Number.isFinite(idleMs) || idleMs < 0) {
    throw new Error(
      'HTTP idle time must be a nonnegative finite number',
    );
  }
  launchServer({ idleMs });
  return idleMs;
}
// settings.get('HTTP_BACKOFF_MS', 5) is only an example.

